INSERT INTO "handovers" ("id","date","shift","author","content","created_at") VALUES(1,'2026-07-09','白班','Chloe Chai',replace('*AM 9/7/2026*\n\n*201* \n*Octenisan, 2x daily*\n*Fucidin, TID: 1030PM*\n☀️ *Sunlight Expose TCM*\n*Nasal duct massage*\nAlternate Frisolac AR - Frisolac \n\n*202*\n💉 *Heparin 8am for 8 days*\n🌿 *Jaundice bath last 10/7*\n☀️ *Sunlight expose* \nIf jaundice 13mg/dl, inform mummy \n*Alternate 30/40, noted*\n\n*203*\n💉 *Heparin 8am & 8pm*\n\n*301*\n🌺 *JYH bath 3days 10-12/7*\n*U/C clean twice*\n*Send BF 15min early,change diaper in mummy room*\n*Clean face after feeding, use remdii*\n\n*306*\n🦵🏻*Club foot massage*\nGo u-turn','\n',char(10)),'2026-07-09T12:15:57.827Z');
INSERT INTO "handovers" ("id","date","shift","author","content","created_at") VALUES(2,'2026-07-09','夜班','Ah Ming',replace('MID 7/7/2026*\n\n*201* BABY BOY\nMiconazole cream Alternate Desitin\nTerramycin ointment BID\n10Am n 10Pm\nSunlight Expose TCM\nExpose buttock\n*Ask mummy jaundice bath*\nAlternate 50ml / 60ml\nCrying after feeding 😢 \n\n*202*\n*Biogaia 5drop AM*\nDischage today 🥳🥳\n\n\n*203*\n💉 *Heparin 8am & 8pm*\n🌿 *Jaundice bath 3 day 7-9/7*\n\n*205*\n🌸 *JYH bath 7/7*\n*Vitamin D 1 Drop AM*\n*BF after 8AM*\n\n*206*\n*Biogaia 5drop AM‼️*\n*Expose Lt big toe*\nUse S size diapers!!\nDischage today 🥳🥳\n\n*207*\n*Yuyee 1shift once*\n*After feeding clean face*\n*Abdomen massage bfr every feeding*\n*MAKE SURE BABY THINGS ALL COMPLETED BEFORE SEND OUT!!!*\nDischage today 🥳🥳\n\n*301*\n*U/C clean twice*\n*Send BF 15min early,change diaper at mummy room*\n*Topup collector, no milk in collector topup 40ml*\n*Clean face after feeding, use remdii*\nCrying wake up early \n\n*302*\n*Use own Huggies diapers*\n*Biogaia 5drop Am*\nMID Feed Frozen milk\nCrying on off\nCrying hard to sleep 😢\n\n*305*\nCrying on off \n\n*306*\n🦵🏻*Club foot massage\nHard to sleep Crying 😢','\n',char(10)),'2026-07-09T12:16:44.320Z');
